import{_ as e,o as d,c as o,ag as c}from"./chunks/framework.BLV0JUXI.js";const h=JSON.parse('{"title":"工程化收尾（阶段五交付）","description":"","frontmatter":{},"headers":[],"relativePath":"ecommerce-mini-program/docs/engineering.md","filePath":"ecommerce-mini-program/docs/engineering.md","lastUpdated":1793854502000}'),a={name:"ecommerce-mini-program/docs/engineering.md"};function r(s,t,i,n,l,p){return d(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="工程化收尾-阶段五交付" tabindex="-1">工程化收尾（阶段五交付） <a class="header-anchor" href="#工程化收尾-阶段五交付" aria-label="Permalink to &quot;工程化收尾（阶段五交付）&quot;">​</a></h1><blockquote><p>范围：单测矩阵、各端 CI 上传、构建体积检查、灰度放量演练、Mock → HttpTransport 转接演练。 所有命令在 <code>ecommerce-mini-program/</code> 下执行。</p></blockquote><h2 id="_1-质量门禁" tabindex="-1">1. 质量门禁 <a class="header-anchor" href="#_1-质量门禁" aria-label="Permalink to &quot;1. 质量门禁&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>失败含义</th></tr></thead><tbody><tr><td><code>pnpm typecheck</code></td><td><code>vue-tsc --noEmit</code>，严格模式全量类型检查</td><td>类型契约被破坏</td></tr><tr><td><code>pnpm test:run</code></td><td>Vitest 一次性运行全部单测</td><td>业务逻辑或降级路径回归</td></tr><tr><td><code>pnpm ci:guard</code></td><td>静态守卫：业务目录禁条件编译、flag 注册表合规、api 不反向依赖 store</td><td>架构边界被破坏</td></tr><tr><td><code>pnpm ci:perf</code></td><td>构建产物体积预算检查（需先 build），并输出与上次的体积趋势</td><td>主包/总体积超限</td></tr><tr><td><code>pnpm run ci</code></td><td>一键流水线：<code>typecheck → test:run → ci:guard → build:all → ci:perf</code></td><td>任一门禁失败即中断</td></tr><tr><td><code>pnpm e2e:marketing</code></td><td>营销端到端回归：拼团 / 秒杀 / 直播，自动起 dev server 并驱动无头 Chrome（H5 + Mock）</td><td>营销链路行为回归</td></tr></tbody></table><p>建议流水线顺序：<code>install → pnpm run ci</code>；上传单独执行 <code>ci:upload:&lt;platform&gt;</code>，营销端到端单独执行 <code>e2e:marketing</code>。仓库已接入 <a href="../../.github/workflows/ci-ecommerce.yml"><code>.github/workflows/ci-ecommerce.yml</code></a>，push / PR 命中 <code>ecommerce-mini-program/**</code> 时自动执行 <code>verify</code> 与 <code>e2e-marketing</code> 两个 job，并把体积历史作为 artifact 保留。</p><h2 id="_2-单测清单与覆盖矩阵" tabindex="-1">2. 单测清单与覆盖矩阵 <a class="header-anchor" href="#_2-单测清单与覆盖矩阵" aria-label="Permalink to &quot;2. 单测清单与覆盖矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>覆盖点</th></tr></thead><tbody><tr><td><code>src/__tests__/utils.spec.ts</code></td><td>金额格式化、优惠券计算、倒计时与分页工具</td></tr><tr><td><code>src/__tests__/flag.spec.ts</code></td><td>flag 判定优先级（关闭 / 白名单 / 分桶）、桶号稳定性</td></tr><tr><td><code>src/__tests__/cart-store.spec.ts</code></td><td>加购合并、数量与勾选变更、金额快照、失效商品清理</td></tr><tr><td><code>src/__tests__/remote-config.spec.ts</code></td><td>缓存损坏 + 远程失败回落默认值；拉取超时回落缓存；远程成功透传 <code>configVersion</code> / <code>grayApis</code>；新 flag 5% → 100% → 关闭；关闭态 <code>reason=DISABLED</code>；订阅通知；桶号不漂移</td></tr><tr><td><code>src/__tests__/transport.spec.ts</code></td><td>默认 LocalMock；域级 <code>gray.api.*</code> 切换 HttpTransport；接口级 <code>grayApis[path]</code> 只切指定接口；切到 Http 后业务 API 同构返回；回滚后不再发真实请求</td></tr><tr><td><code>src/__tests__/marketing-store.spec.ts</code></td><td>拼团创建/参团合并；秒杀 1s→2s 退避轮询至 SUCCESS 终止；查询失败转 FAILED；手动停止后不再轮询</td></tr><tr><td><code>src/__tests__/mock-handlers.spec.ts</code></td><td>售后状态机与重复提交/非法状态/原因过短错误码；收藏幂等切换与商品不存在；配置演练接口的放量、随机 2 接口、reset 与非法动作</td></tr><tr><td><code>src/__tests__/form-schema.spec.ts</code></td><td>字段合法无错误、非法字段逐条文案；<code>visible</code> 隐藏字段不参与校验；地区完整性判断与展示文案</td></tr><tr><td><code>src/__tests__/network-status.spec.ts</code></td><td>网络状态单例：断网 <code>networkType=none</code> → 离线，恢复 wifi → 在线；<code>unknown</code> 不误判离线</td></tr><tr><td><code>src/__tests__/upload.spec.ts</code></td><td>上传队列并发上限 3（实际并发 &gt;1 且 ≤3）、6 张全部成功；失败自动重试 1 次后转 <code>failed</code>，手动 <code>retry</code> 成功；9 张上限与 <code>remove</code> 释放名额</td></tr><tr><td><code>src/__tests__/exposure.spec.ts</code></td><td>注入 <code>createIntersectionObserver</code> 回调：同 id 重复进入只上报一次、不同 id 分别上报、payload 带场景参数；重复 <code>observe</code> 先断开旧观察器；无观察器能力时不抛错</td></tr><tr><td><code>src/__tests__/support.spec.ts</code></td><td>无原生客服 API → <code>fallback</code> 且提供手机号/邮箱；有 API 且 corpId/serviceUrl 齐全 → <code>native</code> 并成功调用；有 API 但未配置 → 仍降级</td></tr><tr><td><code>src/__tests__/track.spec.ts</code></td><td>上报失败时事件保留到本地队列，下次 flush 成功送达并清空；失败后按 1s 退避自动重发，成功后停止排期；重启后恢复未送达队列；待发送队列上限 200 条且丢弃最旧事件</td></tr></tbody></table><p>运行单个文件：<code>pnpm vitest run src/__tests__/remote-config.spec.ts</code>。</p><h2 id="_3-各端-ci-上传" tabindex="-1">3. 各端 CI 上传 <a class="header-anchor" href="#_3-各端-ci-上传" aria-label="Permalink to &quot;3. 各端 CI 上传&quot;">​</a></h2><p>脚本：<code>scripts/ci/upload.mjs</code>，入口命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pnpm ci:upload:weixin    # mp-weixin</span></span>
<span class="line"><span>pnpm ci:upload:alipay    # mp-alipay</span></span>
<span class="line"><span>pnpm ci:upload:toutiao   # mp-toutiao</span></span>
<span class="line"><span>pnpm ci:upload:qq        # mp-qq</span></span>
<span class="line"><span>pnpm ci:upload:baidu     # mp-baidu</span></span>
<span class="line"><span>pnpm ci:upload:all       # 依次上传五端</span></span></code></pre></div><p>加 <code>--build</code> 可先构建后上传：<code>node scripts/ci/upload.mjs mp-weixin --build</code>。 缺少密钥、官方 CLI 或构建产物时脚本<strong>安全跳过并以 exit 0 结束</strong>，不阻塞流水线。</p><h3 id="_3-1-通用环境变量" tabindex="-1">3.1 通用环境变量 <a class="header-anchor" href="#_3-1-通用环境变量" aria-label="Permalink to &quot;3.1 通用环境变量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>CI_VERSION</code></td><td>上传版本号，默认 <code>1.0.&lt;当前分钟数&gt;</code></td></tr><tr><td><code>CI_DESC</code></td><td>版本描述，默认带时间戳</td></tr><tr><td><code>CI_BUILD</code></td><td>设为 <code>1</code> 等价于 <code>--build</code></td></tr></tbody></table><h3 id="_3-2-微信" tabindex="-1">3.2 微信 <a class="header-anchor" href="#_3-2-微信" aria-label="Permalink to &quot;3.2 微信&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>WX_APPID</code></td><td>是</td><td>小程序 AppID</td></tr><tr><td><code>WX_PRIVATE_KEY_PATH</code></td><td>是</td><td>上传私钥文件路径（需存在）</td></tr><tr><td><code>WX_ROBOT</code></td><td>否</td><td>上传机器人编号，默认 1</td></tr></tbody></table><p>依赖 <code>miniprogram-ci</code>：<code>pnpm add -D miniprogram-ci</code>；未安装时跳过。</p><h3 id="_3-3-支付宝" tabindex="-1">3.3 支付宝 <a class="header-anchor" href="#_3-3-支付宝" aria-label="Permalink to &quot;3.3 支付宝&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>ALIPAY_APP_ID</code></td><td>是</td><td>小程序 AppID</td></tr><tr><td><code>ALIPAY_PRIVATE_KEY_PATH</code></td><td>是</td><td>私钥文件路径（需存在）</td></tr><tr><td><code>ALIPAY_PRIVATE_KEY_PASSWORD</code></td><td>否</td><td>私钥密码</td></tr><tr><td><code>ALIPAY_UPLOAD_CMD</code></td><td>否</td><td>自定义上传命令，设置后优先使用</td></tr></tbody></table><p>默认调用官方 CLI <code>minidev upload</code>，未安装时跳过。</p><h3 id="_3-4-抖音-qq-百度" tabindex="-1">3.4 抖音 / QQ / 百度 <a class="header-anchor" href="#_3-4-抖音-qq-百度" aria-label="Permalink to &quot;3.4 抖音 / QQ / 百度&quot;">​</a></h3><p>各端使用「官方开发者工具命令行」上传，脚本仅负责注入环境并执行命令：</p><table tabindex="0"><thead><tr><th>平台</th><th>凭证变量</th><th>上传命令变量</th><th>注入给命令的变量</th></tr></thead><tbody><tr><td>抖音</td><td><code>TT_APP_ID</code> / <code>TT_PRIVATE_KEY_PATH</code></td><td><code>TT_UPLOAD_CMD</code></td><td><code>PROJECT_PATH</code> / <code>APP_ID</code> / <code>VERSION</code> / <code>DESC</code></td></tr><tr><td>QQ</td><td><code>QQ_APP_ID</code> / <code>QQ_PRIVATE_KEY_PATH</code></td><td><code>QQ_UPLOAD_CMD</code></td><td>同上</td></tr><tr><td>百度</td><td><code>BD_APP_ID</code> / <code>BD_PRIVATE_KEY_PATH</code></td><td><code>BD_UPLOAD_CMD</code></td><td>同上</td></tr></tbody></table><p>示例：<code>TT_UPLOAD_CMD=&#39;tt upload --project $PROJECT_PATH --appid $APP_ID --version $VERSION&#39;</code>。</p><h2 id="_4-性能检查" tabindex="-1">4. 性能检查 <a class="header-anchor" href="#_4-性能检查" aria-label="Permalink to &quot;4. 性能检查&quot;">​</a></h2><p><code>pnpm ci:perf</code> 扫描 <code>dist/build/&lt;platform&gt;</code>，按 <code>src/pages.json</code> 的 <code>subPackages[].root</code> 区分主包与分包。</p><table tabindex="0"><thead><tr><th>预算</th><th>默认值</th><th>覆盖方式</th></tr></thead><tbody><tr><td>主包体积</td><td>2MB（支付宝单独 3MB）</td><td>全局 <code>PERF_MAIN_LIMIT_MB</code>；分端 <code>PERF_MAIN_LIMIT_MB_MP_ALIPAY</code></td></tr><tr><td>总体积</td><td>20MB（H5 至少按 10MB 计）</td><td>全局 <code>PERF_TOTAL_LIMIT_MB</code>；分端 <code>PERF_TOTAL_LIMIT_MB_MP_ALIPAY</code></td></tr></tbody></table><p>分端变量优先级：分端环境变量 &gt; 全局环境变量 &gt; 分端默认 &gt; 全局默认。变量名规则 <code>PERF_&lt;MAIN|TOTAL&gt;_LIMIT_MB_&lt;平台大写，非字母数字转下划线&gt;</code>，如 <code>PERF_MAIN_LIMIT_MB_MP_QQ</code>。支付宝 <code>vendor.js</code> 约 0.5MB，故主包默认放宽到 3MB，实际产物 0.76MB 仍有充足余量。</p><p>输出内容：各端总体积 / 主包体积 / 分包数、Top5 大文件、H5 gzip 体积；并与上次记录对比输出增减趋势。超预算 exit 1；无产物时提示后安全退出。</p><p>体积历史默认写入 <code>dist/perf-history.json</code>（保留最近 30 次，可用 <code>PERF_HISTORY_FILE</code> 覆盖），CI 中作为 artifact 上传便于查看趋势。</p><p>专项建议：</p><ul><li>营销页与低頻页面全部放进分包，主包只保留 tabBar 四页与公共组件。</li><li>图片一律走 CDN 或 <code>static</code>，不内联大图；构建前用 <code>pnpm build:&lt;platform&gt;</code> 产出真实数据。</li><li>长列表使用 <code>src/components/business/VirtualList.vue</code>（定高或 <code>dynamic</code> 动态高模式），避免一次性渲染全量节点。</li></ul><h2 id="_5-灰度演练-runbook-5-→-100-→-秒级关闭" tabindex="-1">5. 灰度演练 runbook（5% → 100% → 秒级关闭） <a class="header-anchor" href="#_5-灰度演练-runbook-5-→-100-→-秒级关闭" aria-label="Permalink to &quot;5. 灰度演练 runbook（5% → 100% → 秒级关闭）&quot;">​</a></h2><p>演练 flag：<code>feature.couponCenter</code>（注册于 <code>src/config/flags.ts</code>，默认关闭，Mock 侧默认 100% 可见）。</p><p>前置：<code>pnpm dev:h5</code> 或任一小程序端开发模式（<code>VITE_MOCK_MODE=local</code>），进入「我的」页。</p><ol><li><strong>确认基线</strong>：优惠券中心入口可见；「我的 → 工程演练」显示 <code>开放 · 桶 N · BUCKET</code>。</li><li><strong>5% 放量</strong>：工程演练面板点「5% 放量」。<code>POST /config/flag-drill</code> 写入 <code>{ key, percent: 5, enabled: true }</code>，随后刷新远程配置。 <ul><li>桶号小于 5 的用户入口保留，其余用户入口立即消失；</li><li>面板 toast 会显示当前桶号与命中结果，便于换账号验证。</li></ul></li><li><strong>100% 全量</strong>：点「100% 全量」。同一用户桶号不变（<code>hash(userId + flagKey) % 100</code> 稳定），入口恢复。</li><li><strong>秒级关闭</strong>：点「秒级关闭」（<code>percent: 0, enabled: false</code>）。入口消失，<code>reason=DISABLED</code>；优惠券列表等老数据仍可读取，无报错。</li><li><strong>免手动刷新</strong>：<code>App.vue</code> 在 <code>onShow</code> 启动 10s 配置轮询（<code>CONFIG_REFRESH_INTERVAL</code>），<code>onHide</code> 停止。只改服务端配置、不动客户端，最多 10s 生效；也可在面板操作后立即手动 <code>refresh()</code>。</li><li><strong>验收断言</strong>：关闭态入口消失且无报错；开启态链路完整；同一用户多端多次启动桶号一致（单测 <code>remote-config.spec.ts</code> 已固化 <code>u_1001 → 桶 16</code>）。</li></ol><blockquote><p>生产环境把 <code>/config/flag-drill</code> 换成配置平台写接口即可，客户端逻辑不变。</p></blockquote><h2 id="_6-转接演练-runbook-随机-2-个接口-mock-→-httptransport" tabindex="-1">6. 转接演练 runbook（随机 2 个接口 Mock → HttpTransport） <a class="header-anchor" href="#_6-转接演练-runbook-随机-2-个接口-mock-→-httptransport" aria-label="Permalink to &quot;6. 转接演练 runbook（随机 2 个接口 Mock → HttpTransport）&quot;">​</a></h2><p>实现要点：</p><ul><li><code>src/config/runtime.ts</code> 的 <code>isRealRequest(domain, path)</code> 依次判断：<code>MOCK_MODE=http</code> → 域级 <code>gray.api.&lt;domain&gt;</code> → 接口级 <code>grayApis[path]</code>。</li><li><code>src/transport/index.ts</code> 的 <code>transportFor(domain, path)</code> 按接口选择 Transport，业务 API 不改一行代码。</li><li>Mock <code>POST /config/transport-drill</code> 从候选池（<code>/goods/list</code>、<code>/goods/categories</code>、<code>/goods/detail</code>、<code>/order/list</code>、<code>/favorite/list</code>）随机抽 2 个，或 <code>reset</code> 清空。</li></ul><p>推荐在 H5 演示，真实请求可被现有 msw worker 回归，形成闭环：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># .env.development 已配置 VITE_API_BASE_URL=/api</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VITE_MOCK_MODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">msw</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:h5</span></span></code></pre></div><ol><li>打开「我的 → 工程演练」，点「随机抽取 2 个」，面板展示本次抽中的接口路径。</li><li>触发对应业务：首页/分类加载商品、进入商品详情、订单列表、收藏列表。</li><li>观察 Network：被抽中接口请求 <code>/api/*</code>，由 msw 拦截并返回同构数据；其余接口仍走 LocalMock，无网络请求。</li><li>截图/记录 traceId 头（<code>X-Trace-Id</code>）用于归因。</li><li>点「回滚全部」→ <code>grayApis</code> 清空 → 所有接口回到 Mock；再次触发业务确认无真实请求。</li><li>回归断言：整个过程业务代码零改动；<code>transport.spec.ts</code> 覆盖域级/接口级切换与回滚。</li></ol><p>小程序端演练：把 <code>grayApis</code> 下发到真实后端地址（替换 <code>VITE_API_BASE_URL</code>），流程相同；未接后端时保持 <code>grayApis</code> 为空即可。</p><h2 id="_7-已知限制" tabindex="-1">7. 已知限制 <a class="header-anchor" href="#_7-已知限制" aria-label="Permalink to &quot;7. 已知限制&quot;">​</a></h2><ul><li>微信上传依赖 <code>miniprogram-ci</code>；支付宝依赖 <code>minidev</code>；抖音/QQ/百度依赖各自开发者工具 CLI。仓库不内置这些二进制，CI 需自行安装或提供 <code>*_UPLOAD_CMD</code>。</li><li>缺少真实后端与上传密钥时，上传脚本按设计跳过（exit 0），不会产生假成功。</li><li>体积预算为经验值，可按业务调整 <code>PERF_MAIN_LIMIT_MB</code> / <code>PERF_TOTAL_LIMIT_MB</code>；首次接入请先跑一次 build 建立基线。</li><li>配置轮询间隔固定 10s（常量在 <code>src/config/env.ts</code>），仅前台运行；后台/冷启动依赖启动拉取。</li><li>灰度桶号基于 <code>userId + flagKey</code>，匿名身份（未登录）会随匿名 ID 变化，属预期行为。</li></ul>`,46)])])}const m=e(a,[["render",r]]);export{h as __pageData,m as default};
